/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dsyrk = require( './../lib/dsyrk.js' );


// FIXTURES //

var clnt = require( './fixtures/column_major_l_nt.json' );
var cunt = require( './fixtures/column_major_u_nt.json' );
var clt = require( './fixtures/column_major_l_t.json' );
var cut = require( './fixtures/column_major_u_t.json' );

var rlnt = require( './fixtures/row_major_l_nt.json' );
var runt = require( './fixtures/row_major_u_nt.json' );
var rlt = require( './fixtures/row_major_l_t.json' );
var rut = require( './fixtures/row_major_u_t.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dsyrk, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dsyrk.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = rlnt;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dsyrk( value, data.uplo, data.trans, data.N, data.K, data.alpha, new Float64Array( data.A ), data.lda, data.beta, new Float64Array( data.C ), data.ldc );
		};
	}
});

