tape( 'the function performs the matrix-matrix operation `C = α*A*A^T + β*C` or `C = α*A^T*A + β*C` (row-major, lower, no-transpose)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var c;

	data = rlnt;

	a = new Float64Array( data.A );
	c = new Float64Array( data.C );

	expected = new Float64Array( data.C_out );

	out = dsyrk( data.order, data.uplo, data.trans, data.N, data.K, data.alpha, a, data.lda, data.beta, c, data.ldc );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

